              "type": "object",
              "properties": {
                "label": {
                  "type": "string",
                  "description": "Short display label"
                },
                "description": {
                  "type": "string",
                  "description": "Optional explanatory text shown with the label"
                }
              },
              "required": [
                "label"
              ]
            }
          },
          "multiSelect": {
            "type": "boolean",
            "description": "Allow multiple selections (default: false)"
